cases=[]
for n in [2,3,4,6,8,12]:
 for D in [1,2,3]:
  for pd in [1,2,3]:
   try:
    x=q.TN_rand_tree(n,D,phys_dim=pd,max_degree=3,seed=100+n*10+D*3+pd)
