    ok=math.isclose(float(ref),float(rec),rel_tol=1e-8,abs_tol=1e-10)
    print(n,D,pd,ok,ref,rec,abs(rec-ref)/max(abs(ref),1e-300))
   except Exception as e: print('ERR',n,D,pd,type(e).__name__,e)
